-- Proposed server-only SQLite/D1 schema. Apply only after choosing/configuring the order service.
PRAGMA foreign_keys = ON;
CREATE TABLE suppliers (id TEXT PRIMARY KEY, name TEXT NOT NULL, adapter TEXT, status TEXT NOT NULL DEFAULT 'draft');
CREATE TABLE products (id TEXT PRIMARY KEY, sku TEXT UNIQUE NOT NULL, slug TEXT UNIQUE NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','active','archived')), public_json TEXT NOT NULL, supplier_id TEXT REFERENCES suppliers(id), supplier_product_id TEXT, supplier_cost_cents INTEGER, sourcing_json TEXT, inventory_checked_at TEXT, price_checked_at TEXT, updated_at TEXT NOT NULL);
CREATE TABLE variants (id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id), sku TEXT UNIQUE NOT NULL, options_json TEXT NOT NULL, price_cents INTEGER NOT NULL CHECK(price_cents > 0), supplier_sku TEXT, supplier_cost_cents INTEGER, inventory_status TEXT NOT NULL);
ALTER TABLE variants ADD COLUMN stock_quantity INTEGER CHECK(stock_quantity IS NULL OR stock_quantity >= 0);
-- Store identity-provider subject IDs, never plain text passwords.
CREATE TABLE customers (id TEXT PRIMARY KEY, identity_subject TEXT UNIQUE NOT NULL, email TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE orders (id TEXT PRIMARY KEY, order_number TEXT UNIQUE NOT NULL, customer_id TEXT REFERENCES customers(id), email TEXT NOT NULL, currency TEXT NOT NULL DEFAULT 'USD', subtotal_cents INTEGER NOT NULL, shipping_cents INTEGER NOT NULL, tax_cents INTEGER NOT NULL, total_cents INTEGER NOT NULL, address_json TEXT NOT NULL, payment_status TEXT NOT NULL DEFAULT 'pending', fulfillment_status TEXT NOT NULL DEFAULT 'unfulfilled', payment_provider TEXT, payment_reference TEXT UNIQUE, idempotency_key TEXT UNIQUE NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE order_lines (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), product_id TEXT NOT NULL, variant_id TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity > 0), price_cents INTEGER NOT NULL, snapshot_json TEXT NOT NULL);
CREATE TABLE shipments (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), supplier_id TEXT REFERENCES suppliers(id), supplier_order_reference TEXT, carrier TEXT, tracking_number TEXT, tracking_url TEXT, status TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE adjustments (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), type TEXT NOT NULL CHECK(type IN ('cancellation','refund','return')), status TEXT NOT NULL, amount_cents INTEGER, provider_reference TEXT UNIQUE, reason TEXT, created_at TEXT NOT NULL);
CREATE TABLE webhook_events (provider TEXT NOT NULL, event_id TEXT NOT NULL, processed_at TEXT, PRIMARY KEY(provider,event_id));
CREATE TABLE outbox (id TEXT PRIMARY KEY, order_id TEXT REFERENCES orders(id), kind TEXT NOT NULL, payload_json TEXT NOT NULL, idempotency_key TEXT UNIQUE NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT);
